<?php namespace App\Filament\Resources\StudentClubResource\Pages;use App\Filament\Resources\StudentClubResource;use App\Services\PeriodGuard;use Filament\Resources\Pages\CreateRecord;class CreateStudentClub extends CreateRecord{protected static string $resource=StudentClubResource::class;protected function mutateFormDataBeforeCreate(array $d):array{$p=request()->attributes->get('academic_period');if($p){PeriodGuard::writable($p->id);$d['academic_period_id']=$p->id;}return $d;}}